class IntelligenceWorker(QThread):
    sinOut = pyqtSignal(int, int)

    def __init__(self, parent, images, source, multi_model_flag=False):
        super(IntelligenceWorker, self).__init__(parent)
        self.parent = parent
        self.source = source
        self.images = images
        self.multi_model_flag = multi_model_flag
        self.notif = []

    def run(self):
        index = 0
        total = len(self.images)
        for filename in self.images:
            if self.parent.isVisible == False:
                return
            if self.source.operationCanceled == True:
                return
            index = index + 1
            json_name = osp.splitext(filename)[0] + '.json'
            if os.path.isdir(json_name):
                os.remove(json_name)
            try:
                print('Decoding ' + filename)
                if self.multi_model_flag:
                    s = self.source.get_shapes_of_one(filename, multi_model_flag=True)
                else:
                    s = self.source.get_shapes_of_one(filename)
                s = mathOps.convert_shapes_to_qt_shapes(s)
                self.source.saveLabelFile(filename, s)
            except Exception as e:
                print(e)
            self.sinOut.emit(index, total)

def __init__(self, parent, images, source, multi_model_flag=False):
    super(IntelligenceWorker, self).__init__(parent)
    self.parent = parent
    self.source = source
    self.images = images
    self.multi_model_flag = multi_model_flag
    self.notif = []

class ColoredFormatter(logging.Formatter):

    def __init__(self, fmt, use_color=True):
        logging.Formatter.__init__(self, fmt)
        self.use_color = use_color

    def format(self, record):
        levelname = record.levelname
        if self.use_color and levelname in COLORS:

            def colored(text):
                return termcolor.colored(text, color=COLORS[levelname], attrs={'bold': True})
            record.levelname2 = colored('{:<7}'.format(record.levelname))
            record.message2 = colored(record.msg)
            asctime2 = datetime.datetime.fromtimestamp(record.created)
            record.asctime2 = termcolor.colored(asctime2, color='green')
            record.module2 = termcolor.colored(record.module, color='cyan')
            record.funcName2 = termcolor.colored(record.funcName, color='cyan')
            record.lineno2 = termcolor.colored(record.lineno, color='cyan')
        return logging.Formatter.format(self, record)

def __init__(self, fmt, use_color=True):
    logging.Formatter.__init__(self, fmt)
    self.use_color = use_color

class UniqueLabelQListWidget(EscapableQListWidget):

    def mousePressEvent(self, event):
        super(UniqueLabelQListWidget, self).mousePressEvent(event)
        if not self.indexAt(event.pos()).isValid():
            self.clearSelection()

    def findItemsByLabel(self, label):
        items = []
        for row in range(self.count()):
            item = self.item(row)
            if item.data(Qt.ItemDataRole.UserRole) == label:
                items.append(item)
        return items

    def createItemFromLabel(self, label):
        item = QtWidgets.QListWidgetItem()
        item.setData(Qt.ItemDataRole.UserRole, label)
        return item

    def setItemLabel(self, item, label, color=None):
        qlabel = QtWidgets.QLabel()
        if color is None:
            qlabel.setText('{}'.format(label))
        else:
            qlabel.setText('{} <font color="#{:02x}{:02x}{:02x}">●</font>'.format(label, *color))
        qlabel.setAlignment(Qt.AlignmentFlag.AlignBottom)
        item.setSizeHint(qlabel.sizeHint())
        self.setItemWidget(item, qlabel)

def findItemsByLabel(self, label):
    items = []
    for row in range(self.count()):
        item = self.item(row)
        if item.data(Qt.ItemDataRole.UserRole) == label:
            items.append(item)
    return items

class HTMLDelegate(QtWidgets.QStyledItemDelegate):

    def __init__(self, parent=None):
        super(HTMLDelegate, self).__init__()
        self.doc = QtGui.QTextDocument(self)

    def paint(self, painter, option, index):
        painter.save()
        options = QtWidgets.QStyleOptionViewItem(option)
        self.initStyleOption(options, index)
        self.doc.setHtml(options.text)
        options.text = ''
        style = QtWidgets.QApplication.style() if options.widget is None else options.widget.style()
        style.drawControl(QStyle.ControlElement.CE_ItemViewItem, options, painter)
        ctx = QtGui.QAbstractTextDocumentLayout.PaintContext()
        if option.state & QStyle.StateFlag.State_Selected:
            ctx.palette.setColor(QPalette.ColorRole.Text, option.palette.color(QPalette.ColorGroup.Active, QPalette.ColorRole.HighlightedText))
        else:
            ctx.palette.setColor(QPalette.ColorRole.Text, option.palette.color(QPalette.ColorGroup.Active, QPalette.ColorRole.Text))
        textRect = style.subElementRect(QStyle.SubElement.SE_ItemViewItemText, options)
        if index.column() != 0:
            textRect.adjust(5, 0, 0, 0)
        thefuckyourshitup_constant = 4
        margin = (option.rect.height() - options.fontMetrics.height()) // 2
        margin = margin - thefuckyourshitup_constant
        textRect.setTop(textRect.top() + margin)
        painter.translate(textRect.topLeft())
        painter.setClipRect(textRect.translated(-textRect.topLeft()))
        self.doc.documentLayout().draw(painter, ctx)
        painter.restore()

    def sizeHint(self, option, index):
        thefuckyourshitup_constant = 4
        return QtCore.QSize(self.doc.idealWidth(), self.doc.size().height() - thefuckyourshitup_constant)

def __init__(self, parent=None):
    super(HTMLDelegate, self).__init__()
    self.doc = QtGui.QTextDocument(self)

